import { Component } from "react";
import "./Footer.css";

export default class footer extends Component{
    render(){
     return(
     <footer>   
        <ul className="list">
            <li>facebook</li>
            <li>twitter</li>
            <li>instagram</li>
        </ul>

        <div className="footer-content"> 
            <ul className="list">
                <li>About Us</li>
                <li>Contact Us</li>
            </ul>
        </div>
        <div className="bottom-bar">
            <p>&copy; 2024 TaiLink. All right reserved</p>
        </div>
        </footer>   

        );
    }
}
